package main
import("bytes";"crypto/hmac";"crypto/sha256";"encoding/base64";"encoding/hex";"encoding/json";"os";"os/exec";"path/filepath";"strings";"testing";"filippo.io/age")

func fixtureObject(t *testing.T,s string)object{t.Helper();v,e:=decode([]byte(s));if e!=nil{t.Fatal(e)};return v}
func TestOpenWrtAliasAndLegacyTokens(t *testing.T){a:=newApp("");if a.p("/var/run/home-net-vpn-maintenance.lock")!="/tmp/run/home-net-vpn-maintenance.lock"{t.Fatal("shared OpenWrt lock alias not resolved")};if !bearerToken(strings.Repeat("Legacy_TOKEN+",4)){t.Fatal("legacy token rejected")};if bearerToken(strings.Repeat("x",32)+"\r\nHeader: injected"){t.Fatal("header injection accepted")}}
func clone(t *testing.T,v object)object{b,e:=canonical(v);if e!=nil{t.Fatal(e)};o,e:=decode(b);if e!=nil{t.Fatal(e)};return o}
func signFixture(t *testing.T,c,v object)string{t.Helper();b,e:=canonical(v);if e!=nil{t.Fatal(e)};key,_:=hex.DecodeString(str(c["signing_key"]));h:=hmac.New(sha256.New,key);h.Write(b);return hex.EncodeToString(h.Sum(nil))}
func TestCanonicalMatchesPython(t *testing.T){vectors:=[]string{`{"z":true,"a":"Русский <>& / \"😀\n","integer":9007199254740993,"empty":null}`,`{"slots":["awg_main","awg_backup"],"rebind":{"revision":2,"mapping":{"awg_backup":"awg_main","awg_main":"awg_backup"}},"order_size":2}`,`{"controls":"\b\f\t\r\n\u007f\u2028","zero":0,"negative":-12}`};for _,raw:=range vectors{v:=fixtureObject(t,raw);got,e:=canonical(v);if e!=nil{t.Fatal(e)};cmd:=exec.Command("python3","-c",`import sys,json;sys.stdout.write(json.dumps(json.load(sys.stdin),sort_keys=True,separators=(',',':')))`);cmd.Stdin=strings.NewReader(raw);want,e:=cmd.Output();if e!=nil{t.Fatal("Python oracle unavailable",e)};if !bytes.Equal(got,want){t.Fatalf("canonical wire mismatch: %s != %s",got,want)}}}
func TestIntegerAndJSONBoundaries(t *testing.T){for _,bad:=range []any{true,false,"1",json.Number("1.0"),json.Number("1e0"),json.Number("9223372036854775808")} {if _,ok:=integer(bad);ok{t.Fatal("accepted non-integer",bad)}};for _,raw:=range []string{`{} {}`,`[]`,`null`,`{"n":1}x`}{if _,e:=decode([]byte(raw));e==nil{t.Fatal("accepted invalid response")}};if _,e:=canonical(1.25);e==nil{t.Fatal("floating wire field accepted")}}
func fixtureJob(t *testing.T)(object,object){c:=object{"router":"apartment-main","signing_key":strings.Repeat("11",32)};p:=[]byte("age-encryption.org/v1\nsynthetic");j:=object{"router":"apartment-main","id":strings.Repeat("a",32),"country":"DE","expires":json.Number("2000"),"digest":hash(p),"target":"awg_backup","address":"10.8.1.202/32","commit":true};r:=object{"job":j,"payload":base64.StdEncoding.EncodeToString(p),"signature":signFixture(t,c,j)};return c,r}
func TestJobAuthenticationAndScope(t *testing.T){c,r:=fixtureJob(t);if _,_,e:=verifyJob(c,r);e!=nil{t.Fatal(e)};for _,edit:=range []func(object){func(r object){obj(r["job"])["router"]="dacha-main"},func(r object){obj(r["job"])["target"]="lan"},func(r object){obj(r["job"])["address"]="10.8.1.202/24"},func(r object){obj(r["job"])["expires"]=true},func(r object){obj(r["job"])["country"]="de"},func(r object){r["payload"]="not base64"},func(r object){r["signature"]=strings.Repeat("0",64)}}{bad:=clone(t,r);edit(bad);if _,_,e:=verifyJob(c,bad);e==nil{t.Fatal("accepted unauthenticated job")}};bad:=clone(t,r);obj(bad["job"])["target"]="lan";bad["signature"]=signFixture(t,c,obj(bad["job"]));if _,_,e:=verifyJob(c,bad);e==nil{t.Fatal("signed unsafe target accepted")}}
func TestAcceptVerifiedIsPayloadFree(t *testing.T){c,_:=fixtureJob(t);j:=object{"router":"apartment-main","id":strings.Repeat("b",32),"country":"DE","expires":json.Number("2000"),"kind":"accept_verified","transaction_id":strings.Repeat("a",32),"digest":hash(nil)};r:=object{"job":j,"payload":"","signature":signFixture(t,c,j)};if _,p,e:=verifyJob(c,r);e!=nil||len(p)!=0{t.Fatal(e)};r["payload"]="anything";if _,_,e:=verifyJob(c,r);e==nil{t.Fatal("accept accepted a payload")}}
func TestPlanFreshnessAndOrder(t *testing.T){c:=object{"signing_key":strings.Repeat("22",32),"prepared_revision":json.Number("5")};p:=fixtureObject(t,`{"revision":5,"expires":1100,"slots":["awg_main","awg_backup"],"order_size":2,"order":["awg_backup","awg_main"]}`);response:=object{"plan":p,"plan_signature":signFixture(t,c,p)};if _,e:=verifyPlan(c,response,1000);e!=nil{t.Fatal(e)};for _,edit:=range []func(object){func(p object){p["revision"]=json.Number("4")},func(p object){p["revision"]=true},func(p object){p["expires"]=json.Number("1000")},func(p object){p["expires"]=json.Number("2861")},func(p object){p["order"]=[]string{"awg_main","awg_main"}},func(p object){delete(p,"order_size")},func(p object){p["slots"]=[]string{"lan","awg_backup"}}}{bad:=clone(t,p);edit(bad);r:=object{"plan":bad,"plan_signature":signFixture(t,c,bad)};if _,e:=verifyPlan(c,r,1000);e==nil{t.Fatal("accepted stale or invalid signed plan")}}}
func TestAgeInteroperabilityAndLimits(t *testing.T){a:=newApp(t.TempDir());if e:=a.initIdentity();e!=nil{t.Fatal(e)};id,e:=a.identity();if e!=nil{t.Fatal(e)};var buf bytes.Buffer;w,e:=age.Encrypt(&buf,id.Recipient());if e!=nil{t.Fatal(e)};w.Write([]byte("synthetic credential envelope"));w.Close();encrypted:=append([]byte{},buf.Bytes()...);got,e:=a.decrypt(encrypted);if e!=nil||string(got)!="synthetic credential envelope"{t.Fatal(e)};encrypted[len(encrypted)-1]^=1;if _,e=a.decrypt(encrypted);e==nil{t.Fatal("corruption not detected")};other:=newApp(t.TempDir());other.initIdentity();if _,e=other.decrypt(buf.Bytes());e==nil{t.Fatal("wrong recipient accepted")};for _,b:=range [][]byte{buf.Bytes()[:40],bytes.Repeat([]byte("x"),65537)}{if _,e=a.decrypt(b);e==nil{t.Fatal("invalid ciphertext accepted")}};p:=a.p(identityPath);before,_:=read(p);if e=a.initIdentity();e!=nil{t.Fatal(e)};after,_:=read(p);if !bytes.Equal(before,after){t.Fatal("identity rotated")}}
func TestFilesystemSafety(t *testing.T){root:=t.TempDir();if within(filepath.Join(root,"tmp-evil","file"),filepath.Join(root,"tmp")){t.Fatal("prefix confused with directory")};dir:=filepath.Join(root,"safe");mkdir(dir);target:=filepath.Join(dir,"record");if e:=atomic(target,[]byte("before"));e!=nil{t.Fatal(e)};if e:=exclusive(target,[]byte("bad"));e==nil{t.Fatal("exclusive create replaced a file")};link:=filepath.Join(root,"link");if e:=os.Symlink(dir,link);e==nil{if e=atomic(filepath.Join(link,"record"),[]byte("bad"));e==nil{t.Fatal("followed symlink ancestor")}};b,_:=read(target);if string(b)!="before"{t.Fatal("baseline changed")}}
